tb_script:
#!/bin/bash
set -euo pipefail

cd /home/caliptra-rtl
export CALIPTRA_ROOT=/home/caliptra-rtl

scratch_dir="/home/caliptra-rtl/scratch/pr134_tb"
vf_src="/home/caliptra-rtl/src/integration/config/caliptra_top_tb.vf"
vf_dst="${scratch_dir}/caliptra_top_tb.vf"
tb_dst="${scratch_dir}/pr134_qspi_split_harness.sv"
test_name="qspi_split_interface_compile"

mkdir -p "${scratch_dir}"

emit_result() {
  local status="$1"
  local message="$2"

  echo "HWE_BENCH_RESULTS_START"
  echo "TEST: ${test_name} ... ${status}"
  if [[ -n "${message}" ]]; then
    echo "INFO: ${message}"
  fi
  echo "HWE_BENCH_RESULTS_END"
}

if ! python3 - "${vf_src}" "${vf_dst}" <<'PY'
from pathlib import Path
import sys

vf_src = Path(sys.argv[1])
vf_dst = Path(sys.argv[2])

lines = []
replaced = False
for line in vf_src.read_text().splitlines():
    if line == "${CALIPTRA_ROOT}/src/integration/tb/caliptra_top_tb.sv":
        lines.append("${CALIPTRA_ROOT}/scratch/pr134_tb/pr134_qspi_split_harness.sv")
        replaced = True
    else:
        lines.append(line)

if not replaced:
    raise SystemExit("expected caliptra_top_tb.sv entry not found in caliptra_top_tb.vf")

vf_dst.write_text("\n".join(lines) + "\n")
PY
then
  emit_result "FAIL" "could not build scratch Verilator file list"
  exit 1
fi

write_harness() {
  local oe_port="$1"

  python3 - "${oe_port}" "${tb_dst}" <<'PY'
