run_lint() {
  local oe_port="$1"
  local log_file="${scratch_dir}/verilator_${oe_port}.log"

  write_harness "${oe_port}"
  verilator --lint-only --timing \
    +define+RV_OPENSOURCE \
    +define+CALIPTRA_INTERNAL_QSPI+CALIPTRA_INTERNAL_TRNG+CALIPTRA_INTERNAL_UART \
    -Wno-WIDTH -Wno-UNOPTFLAT -Wno-LITENDIAN -Wno-CMPCONST -Wno-MULTIDRIVEN -Wno-UNPACKED \
    -f "${vf_dst}" \
    --top-module pr134_qspi_split_harness \
    -f /home/caliptra-rtl/src/integration/config/caliptra_top_tb.vlt \
    2>&1 | tee "${log_file}"
}

if run_lint qspi_d_en_o; then
  emit_result "PASS" "accepted output-enable port qspi_d_en_o"
  exit 0
fi

if run_lint qspi_d_oe; then
  emit_result "PASS" "accepted output-enable port qspi_d_oe"
  exit 0
fi

emit_result "FAIL" "caliptra_top did not elaborate with separated QSPI input, output, and output-enable ports"
exit 1

