tb_script:
#!/bin/bash
set -uo pipefail

cd /home/caliptra-rtl

work_dir="/home/caliptra-rtl/.hwebench_pr298"
build_dir="${work_dir}/obj_dir"
tb_file="${work_dir}/rvjtag_tap_idcode_removed_tb.sv"
compile_log="${work_dir}/compile.log"
sim_log="${work_dir}/sim.log"

rm -rf "${work_dir}"
mkdir -p "${work_dir}"

cat >"${tb_file}" <<'SV'
`timescale 1ns/1ps

module rvjtag_tap_idcode_removed_tb;
  localparam int AWIDTH = 7;
  localparam logic [31:0] LEGACY_IDCODE = 32'h5A5A1235;
  localparam logic [31:0] EXPECTED_DTMCS = {17'h0, 3'h0, 2'b0, 6'd7, 4'h1};

  logic trst = 1'b1;
  logic tck = 1'b0;
  logic tms = 1'b1;
  logic tdi = 1'b0;
  logic tdo;
  logic tdoEnable;

  logic [31:0] wr_data;
  logic [AWIDTH-1:0] wr_addr;
  logic wr_en;
  logic rd_en;

  logic [31:0] rd_data = 32'h0;
  logic [1:0] rd_status = 2'b0;

  logic dmi_reset;
  logic dmi_hard_reset;

  logic [2:0] idle = 3'h0;
  logic [1:0] dmi_stat = 2'b0;
  logic [31:1] jtag_id = LEGACY_IDCODE[31:1];
  logic [3:0] version = 4'h1;

  rvjtag_tap dut (.*);

  task automatic jtag_cycle(input logic next_tms, input logic next_tdi, output logic observed_tdo);
    begin
      tms = next_tms;
      tdi = next_tdi;
      #1;
      tck = 1'b1;
      #1;
      tck = 1'b0;
      #1;
      observed_tdo = tdo;
    end
  endtask

  task automatic reset_tap;
    logic throwaway;
    int i;
    begin
      tck = 1'b0;
      tms = 1'b1;
      tdi = 1'b0;
      trst = 1'b0;
      #3;
      trst = 1'b1;
      for (i = 0; i < 5; i++) begin
        jtag_cycle(1'b1, 1'b0, throwaway);
      end
      jtag_cycle(1'b0, 1'b0, throwaway);
    end
  endtask

  task automatic shift_ir(input logic [4:0] instruction);
    logic throwaway;
    int i;
    begin
      jtag_cycle(1'b1, 1'b0, throwaway);
      jtag_cycle(1'b1, 1'b0, throwaway);
      jtag_cycle(1'b0, 1'b0, throwaway);
      jtag_cycle(1'b0, 1'b0, throwaway);
      for (i = 0; i < 5; i++) begin
        jtag_cycle(i == 4, instruction[i], throwaway);
      end
      jtag_cycle(1'b1, 1'b0, throwaway);
      jtag_cycle(1'b0, 1'b0, throwaway);
    end
  endtask

  task automatic scan_dr32(output logic [31:0] value);
    logic observed_tdo;
    int i;
    begin
      value = '0;
      jtag_cycle(1'b1, 1'b0, observed_tdo);
      jtag_cycle(1'b0, 1'b0, observed_tdo);
      jtag_cycle(1'b0, 1'b0, observed_tdo);
      value[0] = observed_tdo;
      for (i = 1; i < 32; i++) begin
        jtag_cycle(i == 31, 1'b0, observed_tdo);
        value[i] = observed_tdo;
      end
      jtag_cycle(1'b1, 1'b0, observed_tdo);
      jtag_cycle(1'b0, 1'b0, observed_tdo);
    end
  endtask

  initial begin
    logic [31:0] dtmcs_value;
    logic [31:0] default_dr_value;

    reset_tap();

    shift_ir(5'b10000);
    scan_dr32(dtmcs_value);
    if (dtmcs_value !== EXPECTED_DTMCS) begin
      $display("Expected DTMCS 0x%08x, observed 0x%08x", EXPECTED_DTMCS, dtmcs_value);
      $fatal(1, "JTAG scan sanity check failed");
    end

    reset_tap();
    scan_dr32(default_dr_value);
    if (default_dr_value == LEGACY_IDCODE) begin
      $display("Observed legacy IDCODE 0x%08x on reset DR scan", default_dr_value);
      $fatal(1, "Legacy IDCODE instruction is still active");
    end

    $display(
      "Observed reset DR scan 0x%08x; legacy IDCODE 0x%08x is no longer exposed",
      default_dr_value,
      LEGACY_IDCODE
    );
    $finish;
  end
endmodule
SV

if ! verilator --binary --sv --timing --top-module rvjtag_tap_idcode_removed_tb \
  -Wno-fatal -Mdir "${build_dir}" \
  "${tb_file}" \
  "/home/caliptra-rtl/src/riscv_core/veer_el2/rtl/dmi/rvjtag_tap.v" \
  >"${compile_log}" 2>&1; then
  cat "${compile_log}"
  echo "HWE_BENCH_RESULTS_START"
  echo "TEST: rvjtag_idcode_removed ... FAIL"
  echo "HWE_BENCH_RESULTS_END"
  exit 1
fi

if ! "${build_dir}/Vrvjtag_tap_idcode_removed_tb" >"${sim_log}" 2>&1; then
  cat "${compile_log}"
  cat "${sim_log}"
  echo "HWE_BENCH_RESULTS_START"
  echo "TEST: rvjtag_idcode_removed ... FAIL"
  echo "HWE_BENCH_RESULTS_END"
  exit 1
fi

cat "${compile_log}"
cat "${sim_log}"
echo "HWE_BENCH_RESULTS_START"
echo "TEST: rvjtag_idcode_removed ... PASS"
echo "HWE_BENCH_RESULTS_END"
exit 0

