tb_file="${workdir}/ecc_add_sub_mod_alter_ready_tb.sv"
build_log="${workdir}/verilator_build.log"
run_log="${workdir}/verilator_run.log"
status=0

rm -rf "${workdir}"
mkdir -p "${workdir}"

cat > "${tb_file}" <<'SV'
`timescale 1ns/1ps

module ecc_add_sub_mod_alter_ready_tb;
    localparam int REG_SIZE = 8;

    logic clk;
    logic reset_n;
    logic zeroize;
    logic add_en_i;
    logic sub_i;
    logic [REG_SIZE-1:0] opa_i;
    logic [REG_SIZE-1:0] opb_i;
    logic [REG_SIZE-1:0] prime_i;
    logic [REG_SIZE-1:0] res_o;
    logic ready_o;

    ecc_add_sub_mod_alter #(
        .REG_SIZE(REG_SIZE)
    ) dut (
        .clk(clk),
        .reset_n(reset_n),
        .zeroize(zeroize),
        .add_en_i(add_en_i),
        .sub_i(sub_i),
        .opa_i(opa_i),
        .opb_i(opb_i),
        .prime_i(prime_i),
        .res_o(res_o),
        .ready_o(ready_o)
    );

    always #5 clk = ~clk;

    task automatic expect_ready_result(input logic [REG_SIZE-1:0] expected);
    begin
        @(posedge clk);
        #1;

        if (!ready_o) begin
            $display("ERROR: ready_o was low when the result should be valid");
            $fatal(1);
        end

        if (res_o !== expected) begin
            $display("ERROR: expected result 0x%0h but got 0x%0h", expected, res_o);
            $fatal(1);
        end

        @(posedge clk);
        #1;

        if (ready_o) begin
            $display("ERROR: ready_o remained asserted for more than one cycle");
            $fatal(1);
        end
    end
    endtask

    initial begin
        clk = 1'b0;
        reset_n = 1'b0;
        zeroize = 1'b0;
        add_en_i = 1'b0;
        sub_i = 1'b0;
        opa_i = '0;
        opb_i = '0;
        prime_i = '0;

        repeat (2) @(posedge clk);
        reset_n = 1'b1;

        @(negedge clk);
        // Launch a single modular-add transaction: (3 + 4) mod 13 = 7.
        add_en_i = 1'b1;
        sub_i = 1'b0;
        opa_i = 8'd3;
        opb_i = 8'd4;
        prime_i = 8'd13;

        @(posedge clk);
        #1;

        add_en_i = 1'b0;

        // Disturb all inputs before ready_o. A correct design must still return 7.
        sub_i = 1'b1;
        opa_i = 8'd9;
        opb_i = 8'd8;
        prime_i = 8'd19;

        expect_ready_result(8'd7);

        $display("TB PASS");
        $finish;
    end
endmodule
SV

if ! verilator \
    --binary \
    --timing \
    -Wno-fatal \
    -Wno-TIMESCALEMOD \
    -Wno-WIDTHEXPAND \
    --top-module ecc_add_sub_mod_alter_ready_tb \
    --Mdir "${workdir}/obj_dir" \
    src/ecc/rtl/ecc_adder.sv \
    src/ecc/rtl/ecc_add_sub_mod_alter.sv \
    "${tb_file}" \
    >"${build_log}" 2>&1; then
    status=1
fi

if [[ ${status} -eq 0 ]]; then
    if ! "${workdir}/obj_dir/Vecc_add_sub_mod_alter_ready_tb" >"${run_log}" 2>&1; then
        status=1
    fi
fi

echo "HWE_BENCH_RESULTS_START"
if [[ ${status} -eq 0 ]]; then
    echo "TEST: ${test_name} ... PASS"
else
    echo "TEST: ${test_name} ... FAIL"
fi
echo "HWE_BENCH_RESULTS_END"

if [[ ${status} -ne 0 ]]; then
    if [[ -f "${build_log}" ]]; then
        echo "[build log tail]"
        tail -n 40 "${build_log}"
    fi
    if [[ -f "${run_log}" ]]; then
        echo "[run log tail]"
        tail -n 40 "${run_log}"
    fi
    exit 1
fi

#!/bin/bash
set -uo pipefail

cd /home/caliptra-rtl

TEST_NAME="hwe_smepmp_pmpcfg_mask"
TEST_LABEL="smepmp_pmpcfg_mask"
TEST_DIR="/home/caliptra-rtl/src/integration/test_suites/${TEST_NAME}"
RUN_DIR="/home/caliptra-rtl/.hwebench_${TEST_NAME}"
RUN_LOG="${RUN_DIR}/${TEST_NAME}.log"

emit_result() {
  echo "TEST: ${TEST_LABEL} ... $1"
}

install -d "${TEST_DIR}" "${RUN_DIR}"

cp /home/caliptra-rtl/src/integration/test_suites/smoke_test_hw_config/caliptra_isr.h \
  "${TEST_DIR}/caliptra_isr.h"

cat > "${TEST_DIR}/${TEST_NAME}.c" <<'EOF'
// SPDX-License-Identifier: Apache-2.0
#include "caliptra_defines.h"
#include "caliptra_isr.h"
#include "printf.h"
#include "riscv-csr.h"
#include <stdint.h>

volatile uint32_t *stdout = (uint32_t *)STDOUT;
volatile uint32_t intr_count = 0;
enum printf_verbosity verbosity_g = LOW;
volatile caliptra_intr_received_s cptra_intr_rcv = {0};

static void fail_test(uint32_t observed, uint32_t expected)
{
    VPRINTF(FATAL,
            "Observed pmpcfg0 low byte 0x%x, expected 0x%x after writing an illegal R=0/W=1 encoding\n",
            observed & 0xffu,
            expected & 0xffu);
    SEND_STDOUT_CTRL(0x1);
    while (1) {
    }
}

void main(void)
{
    uint32_t observed;

    VPRINTF(LOW, "Checking PMP WARL masking when SMEPMP is disabled\n");

    csr_write_pmpcfg0(0x00000000u);
    observed = csr_read_pmpcfg0();
    VPRINTF(LOW, "Initial pmpcfg0 = 0x%x\n", observed);

    csr_write_pmpcfg0(0x00000002u);
    observed = csr_read_pmpcfg0();
    VPRINTF(LOW, "pmpcfg0 after writing 0x2 = 0x%x\n", observed);

    if ((observed & 0xffu) != 0x00u) {
        fail_test(observed, 0x00u);
    }

    VPRINTF(LOW, "Observed expected PMP WARL masking with SMEPMP disabled\n");
    SEND_STDOUT_CTRL(0xff);
    while (1) {
    }
}
EOF

echo "HWE_BENCH_RESULTS_START"

status=1
if timeout 1500 make -C "${RUN_DIR}" -f /home/caliptra-rtl/tools/scripts/Makefile TESTNAME="${TEST_NAME}" verilator 2>&1 | tee "${RUN_LOG}"; then
  if [[ -f "${RUN_DIR}/verilator_sim.log" ]] && grep -Fq "* TESTCASE PASSED" "${RUN_DIR}/verilator_sim.log"; then
    emit_result "PASS"
    status=0
  elif [[ -f "${RUN_DIR}/verilator_sim.log" ]] && grep -Fq "* TESTCASE FAILED" "${RUN_DIR}/verilator_sim.log"; then
    emit_result "FAIL"
  else
    echo "[ERROR] Simulation completed without a recognizable pass/fail marker"
    emit_result "FAIL"
  fi
else
  cmd_status=$?
  if [[ ${cmd_status} -eq 124 ]]; then
    echo "[ERROR] Timed out after 1500 seconds"
  else
    echo "[ERROR] Build or simulation command failed with status ${cmd_status}"
  fi
  emit_result "FAIL"
fi

echo "HWE_BENCH_RESULTS_END"
exit "${status}"

