+        // Check that ECC PRIVKEY is loaded
+        while((lsu_read_32(CLP_ECC_REG_ECC_KV_RD_PKEY_STATUS) & ECC_REG_ECC_KV_RD_PKEY_STATUS_VALID_MASK) == 0);
+
+        // Check that we got a KV error
