  logic [3:0]  ahb_hprot;
  logic [2:0]  ahb_hsize;
  logic [1:0]  ahb_htrans;
  logic        ahb_hwrite;
  logic [63:0] ahb_hwdata;
  logic [63:0] ahb_hrdata;
  logic        ahb_hready;
  logic        ahb_hresp;

  always #5 clk = ~clk;

  assign free_clk = clk;

  axi4_to_ahb #(
    .TAG(1)
  ) dut (
    .clk(clk),
    .free_clk(free_clk),
    .rst_l(rst_l),
    .scan_mode(scan_mode),
    .bus_clk_en(bus_clk_en),
    .clk_override(clk_override),
    .dec_tlu_force_halt(dec_tlu_force_halt),
