    axi_awid = '0;
    axi_awaddr = '0;
    axi_awsize = 3'b010;
    axi_awprot = '0;
    axi_wvalid = 1'b0;
    axi_wdata = '0;
    axi_wstrb = '0;
    axi_wlast = 1'b0;
    axi_bready = 1'b1;

    axi_arvalid = 1'b0;
    axi_arid = '0;
    axi_araddr = '0;
    axi_arsize = 3'b010;
    axi_arprot = '0;
    axi_rready = 1'b1;

    ahb_hrdata = 64'h0123_4567_89ab_cdef;
    ahb_hready = 1'b1;
    ahb_hresp = 1'b0;

    repeat (2) @(negedge clk);
    rst_l = 1'b1;
    repeat (2) @(posedge clk);

    @(negedge clk);
    axi_arvalid = 1'b1;
    axi_araddr = FIRST_ADDR;
    #1;
    if (ahb_htrans !== 2'b10 || ahb_haddr !== FIRST_ADDR) begin
