tb_script:
#!/bin/bash
set -euo pipefail

cd /home/caliptra-rtl

TEST_NAME="axi4_to_ahb_back_to_back_stall"
WORKDIR="/home/caliptra-rtl/.hwe_tbgen_axi4_to_ahb"
TB_FILE="${WORKDIR}/axi4_to_ahb_b2b_tb.sv"
OBJ_DIR="${WORKDIR}/obj_dir"
BUILD_LOG="${WORKDIR}/verilator_build.log"
RUN_LOG="${WORKDIR}/verilator_run.log"

rm -rf "${WORKDIR}"
mkdir -p "${WORKDIR}"

cat > "${TB_FILE}" <<'SV'
`timescale 1ns/1ps

module axi4_to_ahb_b2b_tb;
  import el2_pkg::*;

  logic clk = 1'b0;
  logic free_clk;
  logic rst_l = 1'b0;
  logic scan_mode = 1'b0;
  logic bus_clk_en = 1'b1;
  logic clk_override = 1'b0;
  logic dec_tlu_force_halt = 1'b0;

  logic        axi_awvalid = 1'b0;
  logic        axi_awready;
  logic [0:0]  axi_awid = '0;
  logic [31:0] axi_awaddr = '0;
  logic [2:0]  axi_awsize = '0;
  logic [2:0]  axi_awprot = '0;

  logic        axi_wvalid = 1'b0;
  logic        axi_wready;
  logic [63:0] axi_wdata = '0;
  logic [7:0]  axi_wstrb = '0;
  logic        axi_wlast = 1'b0;

  logic        axi_bvalid;
  logic        axi_bready = 1'b1;
  logic [1:0]  axi_bresp;
  logic [0:0]  axi_bid;

  logic        axi_arvalid = 1'b0;
  logic        axi_arready;
  logic [0:0]  axi_arid = '0;
  logic [31:0] axi_araddr = '0;
  logic [2:0]  axi_arsize = 3'b010;
  logic [2:0]  axi_arprot = '0;

  logic        axi_rvalid;
  logic        axi_rready = 1'b1;
  logic [0:0]  axi_rid;
  logic [63:0] axi_rdata;
  logic [1:0]  axi_rresp;
  logic        axi_rlast;

  logic [31:0] ahb_haddr;
  logic [2:0]  ahb_hburst;
  logic        ahb_hmastlock;
  logic [3:0]  ahb_hprot;
  logic [2:0]  ahb_hsize;
  logic [1:0]  ahb_htrans;
  logic        ahb_hwrite;
  logic [63:0] ahb_hwdata;
  logic [63:0] ahb_hrdata = 64'h0123_4567_89ab_cdef;
  logic        ahb_hready = 1'b1;
  logic        ahb_hresp = 1'b0;

  assign free_clk = clk;
  always #5 clk = ~clk;

  axi4_to_ahb #(
    .TAG(1)
  ) dut (
    .clk(clk),
    .free_clk(free_clk),
    .rst_l(rst_l),
    .scan_mode(scan_mode),
    .bus_clk_en(bus_clk_en),
    .clk_override(clk_override),
    .dec_tlu_force_halt(dec_tlu_force_halt),
    .axi_awvalid(axi_awvalid),
    .axi_awready(axi_awready),
    .axi_awid(axi_awid),
    .axi_awaddr(axi_awaddr),
    .axi_awsize(axi_awsize),
    .axi_awprot(axi_awprot),
    .axi_wvalid(axi_wvalid),
    .axi_wready(axi_wready),
    .axi_wdata(axi_wdata),
    .axi_wstrb(axi_wstrb),
    .axi_wlast(axi_wlast),
    .axi_bvalid(axi_bvalid),
    .axi_bready(axi_bready),
    .axi_bresp(axi_bresp),
    .axi_bid(axi_bid),
    .axi_arvalid(axi_arvalid),
    .axi_arready(axi_arready),
    .axi_arid(axi_arid),
    .axi_araddr(axi_araddr),
    .axi_arsize(axi_arsize),
    .axi_arprot(axi_arprot),
    .axi_rvalid(axi_rvalid),
    .axi_rready(axi_rready),
    .axi_rid(axi_rid),
    .axi_rdata(axi_rdata),
    .axi_rresp(axi_rresp),
    .axi_rlast(axi_rlast),
    .ahb_haddr(ahb_haddr),
    .ahb_hburst(ahb_hburst),
    .ahb_hmastlock(ahb_hmastlock),
    .ahb_hprot(ahb_hprot),
    .ahb_hsize(ahb_hsize),
    .ahb_htrans(ahb_htrans),
    .ahb_hwrite(ahb_hwrite),
    .ahb_hwdata(ahb_hwdata),
    .ahb_hrdata(ahb_hrdata),
    .ahb_hready(ahb_hready),
    .ahb_hresp(ahb_hresp)
  );

  initial begin
    repeat (2) @(negedge clk);
    rst_l = 1'b1;

    // Launch the first read and let it complete normally.
    @(negedge clk);
    axi_arvalid = 1'b1;
    axi_araddr = 32'h0000_0018;
    #1;
    if (ahb_htrans !== 2'b10 || ahb_haddr !== 32'h0000_0018) begin
      $fatal(1, "first read was not driven as a NONSEQ transfer to 0x00000018");
    end

    @(posedge clk);
    #1;
    axi_arvalid = 1'b0;

    // Launch a second back-to-back read, then stall the AHB side.
    @(negedge clk);
    axi_arvalid = 1'b1;
    axi_araddr = 32'h0000_0014;
    ahb_hready = 1'b0;
    #1;
    if (ahb_htrans !== 2'b10 || ahb_haddr !== 32'h0000_0014) begin
      $fatal(1, "second read was not driven as a NONSEQ transfer before the stall");
    end

    @(posedge clk);
    #1;
    axi_arvalid = 1'b0;

    // While stalled, the bridge must keep the request as NONSEQ and preserve
    // the byte offset on HADDR. The buggy baseline changes HTRANS to 2'b11,
    // which masks off HADDR[2:0] and aliases 0x14 to 0x10.
    if (ahb_htrans !== 2'b10) begin
      $fatal(1, "stalled read changed HTRANS to %b instead of keeping NONSEQ", ahb_htrans);
    end
    if (ahb_haddr !== 32'h0000_0014) begin
      $fatal(1, "stalled read changed HADDR to 0x%08x instead of 0x00000014", ahb_haddr);
    end

    $display("PASS: stalled read held HTRANS=%b HADDR=0x%08x", ahb_htrans, ahb_haddr);
    $finish;
  end
endmodule
SV

if ! verilator --binary --sv --timing \
  --top-module axi4_to_ahb_b2b_tb \
  -Wno-fatal \
  -Wno-DECLFILENAME \
  -Wno-UNUSEDSIGNAL \
  -Wno-UNUSEDPARAM \
  -Wno-BLKSEQ \
  -Wno-SYMRSVDWORD \
  -I/home/caliptra-rtl/src/riscv_core/veer_el2/rtl \
  -I/home/caliptra-rtl/src/riscv_core/veer_el2/rtl/include \
  /home/caliptra-rtl/src/riscv_core/veer_el2/rtl/common_defines.sv \
  /home/caliptra-rtl/src/riscv_core/veer_el2/rtl/include/el2_def.sv \
  /home/caliptra-rtl/src/riscv_core/veer_el2/rtl/lib/beh_lib.sv \
  /home/caliptra-rtl/src/riscv_core/veer_el2/rtl/lib/axi4_to_ahb.sv \
  "${TB_FILE}" \
  --Mdir "${OBJ_DIR}" \
  >"${BUILD_LOG}" 2>&1; then
  echo "HWE_BENCH_RESULTS_START"
  echo "TEST: ${TEST_NAME} ... FAIL"
  echo "HWE_BENCH_RESULTS_END"
  cat "${BUILD_LOG}"
  exit 1
fi

if ! "${OBJ_DIR}/Vaxi4_to_ahb_b2b_tb" >"${RUN_LOG}" 2>&1; then
  echo "HWE_BENCH_RESULTS_START"
  echo "TEST: ${TEST_NAME} ... FAIL"
  echo "HWE_BENCH_RESULTS_END"
  cat "${RUN_LOG}"
  exit 1
fi

echo "HWE_BENCH_RESULTS_START"
echo "TEST: ${TEST_NAME} ... PASS"
echo "HWE_BENCH_RESULTS_END"
cat "${RUN_LOG}"
